#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-22

# Regression test for model-recency-scan.py superseded() (2026-09-22).
#
# The scanner exempts a bare ID that the alias target extends with a snapshot
# DATE (claude-haiku-4-5 vs claude-haiku-4-5-20251001): same model, no date.
# It used to exempt ANY hyphenated extension, so when the `opus` alias moved
# claude-opus-5 -> claude-opus-5-5 the gate read Opus 5 as current and every
# live Opus 5 recommendation passed with a clean 0. This pins both halves:
# a date remainder stays exempt, a version remainder is reported.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCAN="$SCRIPT_DIR/model-recency-scan.py"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/recency-exempt.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

mkdir -p "$WORK/src/skills/fixture" "$WORK/src/agents"
cat > "$WORK/vocab.json" <<'JSON'
{
  "aliases": {"opus": "claude-opus-5-5", "haiku": "claude-haiku-4-5-20251001"},
  "fullIds": ["claude-opus-5-5", "claude-opus-5", "claude-haiku-4-5", "claude-haiku-4-5-20251001"]
}
JSON
cat > "$WORK/src/skills/fixture/SKILL.md" <<'MD'
```python
client.messages.create(model="claude-opus-5", max_tokens=1024)
client.messages.create(model="claude-haiku-4-5", max_tokens=1024)
client.messages.create(model="claude-opus-5-5", max_tokens=1024)
```
MD

REPORT="$(cd "$WORK" && VOCAB_FILE="$WORK/vocab.json" python3 "$SCAN")"
recs="$(printf '%s' "$REPORT" | jq -r '.recommendations')"

fail=0
if [[ "$recs" == "1" ]]; then
  echo "PASS: exactly one superseded recommendation (claude-opus-5)"
else
  echo "FAIL: expected 1 superseded recommendation, got '$recs'"
  echo "  claude-opus-5 must be reported (a -5 remainder is a new version);"
  echo "  claude-haiku-4-5 must stay exempt (a -YYYYMMDD remainder is a snapshot date)."
  fail=1
fi
exit "$fail"
